import React from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, CircularProgress, Alert, Avatar, Chip,
} from '@mui/material';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import PersonIcon from '@mui/icons-material/Person';
import { keyframes } from '@mui/system';

const fadeIn = keyframes`from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); }`;

const depthColors = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6', '#8b5cf6'];

const OrgNode = ({ node, depth }) => {
  const color = depthColors[depth % depthColors.length];
  const hasChildren = node.children?.length > 0;
  const hasEmployees = node.employees?.length > 0;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', position: 'relative' }}>
      {/* Node Card */}
      <Box sx={{
        display: 'flex', flexDirection: 'column', alignItems: 'center',
        animation: `${fadeIn} 0.4s ease ${depth * 0.08}s both`,
      }}>
        <Box sx={{
          width: 240, p: 2, mb: 0.5,
          borderRadius: 2,
          background: `linear-gradient(135deg, ${color}14, ${color}08)`,
          border: `1.5px solid ${color}40`,
          backdropFilter: 'blur(10px)',
          textAlign: 'center',
          position: 'relative',
          transition: 'all 0.3s ease',
          '&:hover': {
            transform: 'translateY(-2px)',
            boxShadow: `0 8px 24px ${color}20`,
            border: `1.5px solid ${color}80`,
          },
        }}>
          <Avatar sx={{
            width: 44, height: 44, mx: 'auto', mb: 1,
            background: `linear-gradient(135deg, ${color}, ${color}88)`,
            fontSize: 18, fontWeight: 700,
          }}>{node.title?.charAt(0)}</Avatar>
          <Typography variant="body2" fontWeight={700} sx={{ mb: 0.3 }}>{node.title}</Typography>
          <Typography variant="caption" color="textSecondary">
            {node.department_name || ''}
          </Typography>
          {hasEmployees && (
            <Box sx={{ mt: 1, pt: 1, borderTop: `1px solid ${color}20` }}>
              {node.employees.slice(0, 3).map(emp => (
                <Chip
                  key={emp.id}
                  avatar={<Avatar sx={{ width: 20, height: 20, fontSize: 10, bgcolor: color }}>{emp.full_name?.charAt(0)}</Avatar>}
                  label={emp.full_name}
                  size="small"
                  sx={{ mb: 0.3, mr: 0.3, fontSize: 10, height: 22 }}
                />
              ))}
              {node.employees.length > 3 && (
                <Chip label={`+${node.employees.length - 3} نفر`} size="small" variant="outlined"
                  sx={{ fontSize: 10, height: 22 }} />
              )}
            </Box>
          )}
        </Box>

        {/* Vertical connector down */}
        {hasChildren && (
          <Box sx={{ width: 2, height: 24, bgcolor: `${color}30`, flexShrink: 0 }} />
        )}
      </Box>

      {/* Children row */}
      {hasChildren && (
        <Box sx={{ position: 'relative', pt: 0 }}>
          {/* Horizontal connector */}
          {node.children.length > 1 && (
            <Box sx={{
              position: 'absolute', top: 0, left: '50%',
              height: 2, bgcolor: `${color}30`,
              transform: 'translateX(-50%)',
              width: `${Math.min(node.children.length * 130, 600)}px`,
              maxWidth: 'calc(100% - 40px)',
            }} />
          )}

          {/* Child connectors */}
          <Box sx={{ display: 'flex', gap: 3, justifyContent: 'center', pt: 2, flexWrap: 'wrap' }}>
            {node.children.map(child => (
              <Box key={child.id} sx={{ position: 'relative' }}>
                {/* Vertical line up from child */}
                <Box sx={{
                  position: 'absolute', top: -10, left: '50%',
                  width: 2, height: 12, bgcolor: `${color}30`,
                  transform: 'translateX(-50%)',
                }} />
                <OrgNode node={child} depth={depth + 1} />
              </Box>
            ))}
          </Box>
        </Box>
      )}
    </Box>
  );
};

const OrgChartPage = () => {
  const { t } = useTranslation();
  const { data, isLoading, error } = useQuery({
    queryKey: ['orgchart-tree'],
    queryFn: () => axiosInstance.get('/org-chart/positions/tree/').then(r => r.data),
  });

  return (
    <Box>
      {/* Header */}
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 4 }}>
        <Avatar sx={{
          width: 52, height: 52,
          background: 'linear-gradient(135deg, #6366f1, #ec4899)',
          boxShadow: '0 6px 20px rgba(99,102,241,0.35)',
        }}>
          <AccountTreeIcon sx={{ fontSize: 30, color: '#fff' }} />
        </Avatar>
        <Box>
          <Typography variant="h4" fontWeight={800}>{t('orgchart.title')}</Typography>
          <Typography variant="body2" color="textSecondary">نمودار ساختار سازمانی</Typography>
        </Box>
      </Box>

      {/* Content */}
      <Paper sx={{
        p: 4, overflow: 'auto', minHeight: 400,
        background: 'linear-gradient(135deg, rgba(255,255,255,0.5), rgba(255,255,255,0.3))',
        backdropFilter: 'blur(20px)',
        borderRadius: 3,
      }}>
        {isLoading ? (
          <Box sx={{ textAlign: 'center', p: 8 }}><CircularProgress /></Box>
        ) : error ? (
          <Alert severity="error" sx={{ borderRadius: 2 }}>
            خطا در دریافت چارت. دستور زیر را اجرا کنید:
            <Box component="code" sx={{ display: 'block', mt: 1, p: 1, bgcolor: 'rgba(0,0,0,0.05)', borderRadius: 1 }}>
              cd C:\HRMS\hrms_project && python manage.py setup_dev
            </Box>
          </Alert>
        ) : !data || data.length === 0 ? (
          <Box sx={{ textAlign: 'center', p: 8 }}>
            <AccountTreeIcon sx={{ fontSize: 64, color: 'text.disabled', mb: 2 }} />
            <Typography variant="h6" color="textSecondary" gutterBottom>چارت سازمانی خالی است</Typography>
            <Typography variant="body2" color="textDisabled" sx={{ mb: 2 }}>
              برای ایجاد چارت سازمانی با ۹ پوزیشن و ۸ پرسنل:
            </Typography>
            <Paper variant="outlined" sx={{ p: 2, display: 'inline-block', textAlign: 'left', bgcolor: 'rgba(0,0,0,0.02)', borderRadius: 2 }}>
              <code style={{ fontSize: 13 }}>
                cd C:\HRMS\hrms_project<br />
                python manage.py setup_dev<br />
                python manage.py runserver
              </code>
            </Paper>
          </Box>
        ) : (
          <Box sx={{ display: 'flex', justifyContent: 'center', pt: 2, pb: 4 }}>
            {data.map(node => (
              <OrgNode key={node.id} node={node} depth={0} />
            ))}
          </Box>
        )}
      </Paper>
    </Box>
  );
};

export default OrgChartPage;
